class IntersPaymentController extends Controller
{

    /** @var  IntersRepository */
    protected $intersRepository;
    protected $deletedService;
    protected $percentRobus;
    protected $validatedamountDays;
    protected $notificationPayment;
    protected $interServices;

    public function __construct(IntersRepository $inter_Reposi ,
    DeletedService $deletedService,
    PercentRobusAuthService $percentRobus,
    ValidateDailyLimitService $validatedamountDays,
    InterPaymentService $interServices)
    {
        $this->intersRepository = $inter_Reposi;
        $this->deletedService = $deletedService;
        $this->percentRobus = $percentRobus;
        $this->validatedamountDays = $validatedamountDays;
        $this->interServices = $interServices;
    }

    /**
     * @OA\POST(
     *      path="/user/inters/store",
     *      tags={"Inter transfer User"},
     *      summary="Create new inter  transfer user",
     *      description="Faire des tarnsfers a l'internationnal 
     *       Selon les id des providers nous faisons nos verifications.
     *        Si provider_id =  9 (Robus)  nous verifions si le clients le numero n'est pas du clients pour eviter les rechargement de son compte.
     *                  Le client saisie le numero robus(9 chiffres) number_compte , sont montant(amount) et le pays,
     *                  le numero doit etre de robus. 
     *        Si provider_id =  1 (MTN) ou 4(Orange)  ou 3(Moov)  ou 6(Wave) le clients saisie le numero de telephone a l'internationnal , le montant et selectionnez le pays.
     *        Le cas ou c'est un numero, le numero doit etre pour un client et qui est de robus.
     *        Le clients ne peux s'auto envoyer de l'argent donc se recharger.
     *        le clients doit avoir le moment necessaire avec la commissions pour faire des transactions dans le cas contraire un warring.    
     *         ",
     *  @OA\Parameter(
     *         in="path",
     *         name="provider",
     *         required=true,
     *         @OA\Schema(type="integer")
     *     ),
     * @OA\Response(
     *          response=200,
     *          description="success Pour un exemple sur une Paiement en CIV avec un numero robus",
     *          @OA\JsonContent(
     *              @OA\Property(property="id", type="number", example=1),
     *              @OA\Property(property="provider", type="string", example="9"),
     *              @OA\Property(property="wallet_id", type="string", example="CIAZE3SD"),
     *              @OA\Property(property="description", type="string", example="Demande de transfers a l'inter"),
     *              @OA\Property(property="amount", type="number", example="1000"),
     *              @OA\Property(property="status", type="string", example="Pending"),
     *              @OA\Property(property="update_at", type="string", example="2022-08-11T09:25:53.000000Z")
     *          )
     *     ),
     *  @OA\RequestBody(
     *         @OA\MediaType(
     *             mediaType="application/json",
     *             @OA\Schema(
     *                 @OA\Property(
     *                      type="object",
     *                      @OA\Property(
     *                          property="provider",
     *                          type="number"
     *                      ),
     *                    @OA\Property(
     *                          property="number_compte",
     *                          type="string"
     *                      ),
     *                    @OA\Property(
     *                          property="amount",
     *                          type="number"
     *                      ),
     *                 @OA\Property(
     *                          property="country",
     *                          type="integer"
     *                      ),
     *               @OA\Property(
     *                          property="description",
     *                          type="string"
     *                      ),
     *                 ),
     *                 example={
     *
     *                     "provider":"9",
     *                     "number_compte":"CIAZE3SD",
     *                     "amount":"1000",
     *                     "country" : 107,
     *                }
     *          
     *             )
     *         )
     *      ),
     *   @OA\Response(
     *          response=333,
     *          description="The number is not found or is not custumers."
     *      ),
     *  @OA\Response(
     *          response=341,
     *          description="Verifier votre solde."
     *      ),
     * @OA\Response(
     *      response=433,
     *      description="Bad Request"
     *   ),
     * @OA\Response(
     *      response=404,
     *      description="not found"
     *   ),
     * 
     *  ),
     */
    public function create_inter(Request $request)
    {
        $rt = rand(40, 5000) * time();
        $tr = str_shuffle('123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ');
        $transactionCode = sprintf("%0.9s", str_shuffle($rt . $tr));
        $transactionCompiCode = sprintf("%0.8s", str_shuffle($rt . $tr));
        $wallet_user = robus();
        $countries = Country::whereId($request->country)->whereRobus(true)->first();
        $offers =  Offer::whereId($request->offer)->where('status', true)->first();
        $amount_days = $this->validatedamountDays->getCeilingProperty();
        $valeur_ceiling  =  robus()->silver_ceiling;
        $admin_civ = $this->validatedamountDays->adminCiv();

        try {
        // Is transaction Or Withdrawal
            if ($request->provider_type == 1) {

                // Is Robus providers

                if ($request->provider == 51) {


                    $validator = Validator::make(

                        $request->all(),
                        [
                            'number_compte' => 'required',
                            'amount' => 'required',
                            'country' => 'required',
                        ],
                        [

                            'number_compte.required' => 'Votre numero est obligatoire',
                            'amount.required' => 'Votre montant est obligatoire',
                            'country.required' => 'Votre pays est obligatoire',

                        ]

                    );

                    if ($validator->fails()) {
                        return response()->json(
                            [
                                'success' => false,
                                'message' => 'Champ est requis',
                                'data' => $validator->errors()
                            ],
                            333
                        );
                    }


                    $wallet_search_acount = Wallet::where('wallet_id', '=',  $request->number_compte)
                                                        ->where('country_id', $request->country)
                                                        ->first();


                    if ($wallet_search_acount == null  || $request->number_compte ==  $wallet_user->wallet->wallet_id  || $wallet_search_acount->sidUser->is_custumers === false ||  $request->country  ==  $wallet_user->wallet->country->id) {

                        return response()->json([
                            'success' => false,
                            'message' => 'The number is not found or is not custumers is not country',
                        ], 333);

                    } else {

                        //  Verifier transfers Som days

                        if ($amount_days >=  $valeur_ceiling) {
                            return response()->json(
                                [
                                    'success' => false,
                                    'message' => 'Votre montant journier est atteint !',
                                ],
                                333
                            );
                        } else {

                            if($wallet_user->country->code == 'CF')
                            {

                                $percent_robus = TransactionCost::whereId(4)->first();

                                // Verify valeur amount max in Landing the ROBUS
                                $valeur_end = $percent_robus->levelTransactionIvoires->last();

                                if ($valeur_end->amount_end < $request->amount) {

                                    return response()->json([
                                        'success' => false,
                                        'message' => 'Vous avez depassez le montant maxi',
                                    ], 350);

                                } else {

                                    foreach($percent_robus->levelTransactionIvoires as $amount_user) {
                                        
                                        if($request->amount  >= $amount_user->amount_begin && $request->amount  <= $amount_user->amount_end) {

                                            $val_amount = $request->amount;

                                            if ($val_amount > $wallet_user->wallet->amount) {

                                                return response()->json([
                                                    'success' => false,
                                                    'message' => 'Verifier votre solde',
                                                ], 341);
                
                                            }else {

                                                $amount_solde =  $wallet_user->wallet->amount -  $val_amount ;
                                    
                                                
                                                $walletInter = $this->intersRepository->create([
                                                    'wallet_id' =>   $wallet_user->wallet->id,
                                                    'amount_solde' => $amount_solde ?? null,
                                                    'amount' => $request->amount,
                                                    'description'  => $request->description ?? 'demande de transfers a l\'internationnal',
                                                    'inter_cost_id' => null,
                                                    'transaction_cost_id' => $percent_robus->id,
                                                    'phone'   => $request->phone ?? null,
                                                    'number_compte'   => $request->number_compte ?? null,
                                                    'created_by' => Auth::guard('api')->user()->id,
                                                    'provider_id'  =>    $request->provider,
                                                    'status'  => "SUCCESS",
                                                    'costs_amount' => $amount_user->amount,
                                                    'provider_type' =>  1,
                                                    'country_id'  =>    $request->country ?? null,
                                                    'amount_received'  => $request->amount -  $amount_user->amount,
                                                ]);
                
                                                $commission =  $val_amount;
                
                                                $wallet_user->wallet->update([
                                                    'reload_by' => Auth::guard('api')->user()->firstname . ' ' . Auth::guard('api')->user()->lastname,
                                                    'sid_user_relod' => Auth::guard('api')->user()->id,
                                                    'amount' => DB::raw('amount-'  .  $commission),
                
                                                ]);
                
                                                // Send amount Users
                                                $valeur_receive =  $walletInter->amount - $amount_user->amount;
                    
                                                // Send in compte User and name reload
                                                $wallet_search_acount->update([
                                                    'reload_by' => Auth::guard('api')->user()->firstname .' ' . Auth::guard('api')->user()->lastname,
                                                    'sid_user_relod' => Auth::guard('api')->user()->id,
                                                    'amount' => DB::raw('amount+' . $valeur_receive),
                                                ]);
                
                                                $transaction_inter = TransactionInter::create([
                                                    'wallet_inter_id' => $walletInter->id,
                                                    'sid_user_id' => Auth::guard('api')->user()->id,
                                                    'transaction_id' => 'RB_' . $walletInter->provider->name . '_' . $transactionCode,
                                                    'operator_transaction_name' =>  $walletInter->provider->name,
                                                    'trans_comp_id' => 'RB_' . $transactionCompiCode,
                                                    'pay_amount' =>  $walletInter->amount,
                                                    'fee_amount' =>   $walletInter->costs_amount,
                                                    'received_amount' => ($walletInter->amount),
                                                    'status'  =>    $walletInter->status,
                                                ]);
                
                                                InvoiceInter::create([
                                                    'title' => "Transfers d'argent",
                                                    'wallet_inter_id' => $walletInter->id,
                                                    'transaction_inter_id' =>  $transaction_inter->id,
                                                    'company_id' => Auth::guard('api')->user()->company->id,
                                                    'description' => $walletInter->description,
                                                    'status'  =>    $walletInter->status,
                                                    'created_by'  =>   Auth::guard('api')->user()->id,
                                                ]);
                
                                                if($wallet_user->is_under_distributer == 1) 
                                                {
                
                                                    // Valur off commission
                                                    $commission_valeur =  $amount_user->amount;
                        
                                                    // 50 %
                                                    $valuer_admin = $percent_robus->percent_admin *  $commission_valeur;
                
                                                    // 20%
                                                    $valuer_deposit = $percent_robus->percent_deposit *  $commission_valeur;
                
                                                    // 30%
                                                    $valuer_with_drawal = $percent_robus->percent_with_drawal *  $commission_valeur;
                                                
                                                    $walletInter->update([
                                                        'commissions' => DB::raw('commissions+'  . $valuer_deposit),
                
                                                    ]);

                                                    if ($admin_civ->count() > 0) {
            
                                                        $nmbre_admin = $admin_civ->count();
            
                                                        $admin_valeur = $valuer_admin + $valuer_with_drawal ;

                                                        $valeur_single = $admin_valeur / $nmbre_admin;
                                            
                                                        foreach ($admin_civ as $user) {
                                                            $admin_single = SidUser::find($user->id);
                                                            AdminsCom::create([
                                                                'amount' =>   $valeur_single,
                                                                'sid_user_id' =>   $admin_single->id,
                                                                'wallet_transaction_id' => null,
                                                                'wallet_bank_id' =>null,
                                                                'wallet_deposit_id' =>null,
                                                                'amount_with_draw' =>  0,
                                                                'wallet_inter_id' =>  $walletInter->id,
                                                                'wallet_payment_id' => null,
                                                                'wallet_phone_credit_id' => null,
                                                                'wallet_reload_id' => null,
                                                                'bank_card_id' => null,
                                                                'description' => 'Commission' ,
                                                            ]);
                                                            $admin_single->wallet->update([
                                                                'reload_by' => Auth::guard('api')->user()->firstname .
                                                                    ' ' .
                                                                    Auth::guard('api')->user()->lastname,
                                                                'sid_user_relod' => Auth::guard('api')->user()->id,
                                                                'amount' => DB::raw('amount+' . $valeur_single),
                                                            ]);
                                                        }
                                                    }
                
                                                        $msg = 'Demande en cours de validation';
                                                        $msg_title = 'Paiement internationnal';
                                                        $wallet_user->notify(new UserNotification(
                                                            [
                                                                'title' => $msg_title,
                                                                'message' => $msg
                                                            ]
                                                        ));
                                                        $notifs = $wallet_user->unreadNotifications;
                        
                                                        $wallet_search_acount->sidUser->notify(new UserNotification([
                                                            'title' => $msg_title,
                                                            'message' => $msg
                                                        ]));
                        
                                                        $notifs = $wallet_search_acount->sidUser->unreadNotifications;
                                                        event(new CreateWalletInterEvent($walletInter));
                                                        $admins = SidUser::whereStatus(true)->whereIsAdmin(true)->where('country_id', $walletInter->country_id)->get();
                                                        Notification::send($admins, new AdminNotification('Demande de paiement de ' . ' ' . $walletInter->wallet->sidUser->firstname));

                                                        if ($admins->count() > 0) {
                        
                                                            foreach ($admins  as $user) {
                        
                                                                $admin_single = SidUser::find($user->id);
                        
                                                                $notifs = $admin_single->unreadNotifications;
                        
                                                                event(new AdminNotifEvent($notifs));
                                                            }
                                                            if ($wallet_user->email != null) {
                        
                                                                $notify = new MailController;
                                                                $notify->newPaiementInter($walletInter);
                                                            }
                                                            return response()->json([
                                                                'success' => true,
                                                                'data' => [
                                                                    'id'      => $walletInter->id,
                                                                    'provider' => $walletInter->provider->name,
                                                                    'amount' => $walletInter->amount,
                                                                    'phone' => $walletInter->phone,
                                                                    'number_compte'   => $walletInter->number_compte,
                                                                    'description' => $walletInter->description,
                                                                    'country'  =>   $walletInter->country->name ?? null,
                                                                    'status' => $walletInter->status,
                                                                ],
                                                                'message' => ('Transfert inter  créé avec succès.')
                                                            ], 200);
                                                        } else {
                        
                                                            if ($wallet_user->email != null) {
                        
                                                                $notify = new MailController;
                                                                $notify->newPaiementInter($walletInter);
                                                            }
                                                            return response()->json([
                                                                'success' => true,
                                                                'data' => [
                                                                    'id'      => $walletInter->id,
                                                                    'provider' => $walletInter->provider->name,
                                                                    'amount' => $walletInter->amount,
                                                                    'phone' => $walletInter->phone,
                                                                    'number_compte'   => $walletInter->number_compte,
                                                                    'description' => $walletInter->description,
                                                                    'country'  =>   $walletInter->country->name ?? null,
                                                                    'status' => $walletInter->status,
                                                                ],
                                                                'message' => ('Transfert inter  créé avec succès.')
                                                            ], 200);
                                                        }

                                                }else {

                                                    // Valur off commission
                                                    $commission_valeur =  $amount_user->amount;
            
                                                    if ($admin_civ->count() > 0) {
            
                                                        $nmbre_admin = $admin_civ->count();
            
                                                        $valeur_single = $commission_valeur / $nmbre_admin;
                                                    
    
                                                        foreach ($admin_civ as $user) {
                                                            $admin_single = SidUser::find($user->id);
                                                            AdminsCom::create([
                                                                'amount' =>   $valeur_single,
                                                                'sid_user_id' =>   $admin_single->id,
                                                                'wallet_transaction_id' => null,
                                                                'wallet_bank_id' =>null,
                                                                'wallet_deposit_id' =>null,
                                                                'amount_with_draw' =>  0,
                                                                'wallet_inter_id' =>  $walletInter->id,
                                                                'wallet_payment_id' => null,
                                                                'wallet_phone_credit_id' => null,
                                                                'wallet_reload_id' => null,
                                                                'bank_card_id' => null,
                                                                'description' => 'Commission' ,
                                                            ]);
                                                            $admin_single->wallet->update([
                                                                'reload_by' => Auth::guard('api')->user()->firstname .
                                                                    ' ' .
                                                                    Auth::guard('api')->user()->lastname,
                                                                'sid_user_relod' => Auth::guard('api')->user()->id,
                                                                'amount' => DB::raw('amount+' . $valeur_single),
                                                            ]);
                                                        }
                                                    }

                                                    $msg = 'Demande en cours de validation';
                                                    $msg_title = 'Paiement internationnal';
                                                    $wallet_user->notify(new UserNotification(
                                                        [
                                                            'title' => $msg_title,
                                                            'message' => $msg
                                                        ]
                                                    ));
                                                    $notifs = $wallet_user->unreadNotifications;
                    
                                                    $wallet_search_acount->sidUser->notify(new UserNotification([
                                                        'title' => $msg_title,
                                                        'message' => $msg
                                                    ]));
                    
                                                    //  Convertion of amount valeur
                                                    
                                                    $notifs = $wallet_search_acount->sidUser->unreadNotifications;
                                                    event(new CreateWalletInterEvent($walletInter));
                                                    $admins = SidUser::whereStatus(true)->whereIsAdmin(true)->where('country_id', $walletInter->country_id)->get();
                                                    Notification::send($admins, new AdminNotification('Demande de paiement de ' . ' ' . $walletInter->wallet->sidUser->firstname));

                                                    if ($admins->count() > 0) {
                    
                                                        foreach ($admins  as $user) {
                    
                                                            $admin_single = SidUser::find($user->id);
                    
                                                            $notifs = $admin_single->unreadNotifications;
                    
                                                            event(new AdminNotifEvent($notifs));
                                                        }
                                                        if ($wallet_user->email != null) {
                    
                                                            $notify = new MailController;
                                                            $notify->newPaiementInter($walletInter);
                                                        }
                                                        return response()->json([
                                                            'success' => true,
                                                            'data' => [
                                                                'id'      => $walletInter->id,
                                                                'provider' => $walletInter->provider->name,
                                                                'amount' => $walletInter->amount,
                                                                'phone' => $walletInter->phone,
                                                                'number_compte'   => $walletInter->number_compte,
                                                                'description' => $walletInter->description,
                                                                'country'  =>   $walletInter->country->name ?? null,
                                                                'status' => $walletInter->status,
                                                            ],
                                                            'message' => ('Transfert inter  créé avec succès.')
                                                        ], 200);
                                                    } else {
                    
                                                        if ($wallet_user->email != null) {
                    
                                                            $notify = new MailController;
                                                            $notify->newPaiementInter($walletInter);
                                                        }
                                                    return response()->json([
                                                    'success' => true,
                                                    'data' => [
                                                        'id'      => $walletInter->id,
                                                        'provider' => $walletInter->provider->name,
                                                        'amount' => $walletInter->amount,
                                                        'phone' => $walletInter->phone,
                                                        'number_compte'   => $walletInter->number_compte,
                                                        'description' => $walletInter->description,
                                                        'country'  =>   $walletInter->country->name ?? null,
                                                        'status' => $walletInter->status,
                                                    ],
                                                    'message' => ('Transfert inter  créé avec succès.')
                                                ], 200);
                                                    }

                                                }
                                        
            
                                            }

                                        }
                                    }    
                                }

                            }elseif($wallet_user->country->code == 'GH') {

                                $percent_robus = TransactionCost::whereId(14)->first();

                                $val_amount = $request->amount ;

                                if ($val_amount > $wallet_user->wallet->amount) {

                                    return response()->json([
                                        'success' => false,
                                        'message' => 'Verifier votre solde',
                                    ], 341);

                                }else {

                                    $valeur_received = $request->amount -  ($percent_robus->percent * $request->amount);

                                    $amount_solde =  $wallet_user->wallet->amount -  $val_amount ;
                                    
                                    
                                    $walletInter = $this->intersRepository->create([
                                        'amount_solde' => $amount_solde ?? null,
                                        'wallet_id' =>   $wallet_user->wallet->id,
                                        'amount' => $request->amount,
                                        'description'  => $request->description ?? 'demande de transfers a l\'internationnal',
                                        'inter_cost_id' => null,
                                        'transaction_cost_id' => $percent_robus->id,
                                        'phone'   => $request->phone ?? null,
                                        'number_compte'   => $request->number_compte ?? null,
                                        'created_by' => Auth::guard('api')->user()->id,
                                        'provider_id'  =>    $request->provider,
                                        'status'  => "SUCCESS",
                                        'costs_amount' => $percent_robus->percent * $request->amount,
                                        'provider_type' =>  1,
                                        'country_id'  =>    $request->country ?? null,
                                        'amount_received'  => $valeur_received * $wallet_user->wallet->currencie->value,
                                    ]);

                                    $commission =  $val_amount;

                                    $wallet_user->wallet->update([
                                        'reload_by' => Auth::guard('api')->user()->firstname .
                                            ' ' . Auth::guard('api')->user()->lastname,
                                        'sid_user_relod' => Auth::guard('api')->user()->id,
                                        'amount' => DB::raw('amount-' . $commission),
                                    ]);

                                    $amount_valeur_received =  $walletInter->amount - ($percent_robus->percent * $request->amount);

                                    // Send amount Users
                                    $valeur_receive =  $amount_valeur_received * $wallet_user->wallet->currencie->value;
                    

                                    // Send in compte User and name reload
                                    $wallet_search_acount->update([
                                        'reload_by' => Auth::guard('api')->user()->firstname .' ' . Auth::guard('api')->user()->lastname,
                                        'sid_user_relod' => Auth::guard('api')->user()->id,
                                        'amount' => DB::raw('amount+' . $valeur_receive),
                                    ]);
    
                                    $transaction_inter = TransactionInter::create([
                                        'wallet_inter_id' => $walletInter->id,
                                        'sid_user_id' => Auth::guard('api')->user()->id,
