                                                                            'provider' => $walletInter->provider->name,
                                                                            'amount' => $walletInter->amount,
                                                                            'phone' => $walletInter->phone,
                                                                            'number_compte'   => $walletInter->number_compte,
                                                                            'description' => $walletInter->description,
                                                                            'country'  =>   $walletInter->country->name ?? null,
                                                                            'status' => $walletInter->status,
                                                                        ],
                                                                        'message' => ('Transfert inter  créé avec succès.')
                                                                    ], 200);
                                                                }

                
                                                        }
                                                    }

                                                }
                                            }
                                        }
                                    }

                                }

                        }
                    }
                }
        
            }   
         } catch (\Exception $exception) {
            return response()->json([
                'success' => false,
                'message' => 'une erreur inattendue s\'est produite. veuillez informer Support client ROBUS',
            ], 333);
        }
    }

    /**
     * Get Detail reload card
     * @OA\Get (
     *      path="/user/inter/show/{id}",
     *      tags={"Inter transfer User"},
     *      summary="Show details inter",
     *      description="Details sur les paiements a l'internationnal  donc la facture",   
     *  @OA\Parameter(
     *         in="path",
     *         name="id",
     *         required=true,
     *         @OA\Schema(type="integer")
     *     ),
     *     @OA\Response(
     *         response=200,
     *         description="success",
     *         @OA\JsonContent(
     *              @OA\Property(property="id", type="number", example=1),
     *              @OA\Property(property="provider", type="string", example="9"),
     *              @OA\Property(property="amount", type="double", example="1000"),
     *              @OA\Property(property="reference", type="string", example="robus_1205255111_test"),
     *              @OA\Property(property="decription", type="string", example="Demande de transfers"),
     *              @OA\Property(property="country", type="string", example="CIV"),
     *              @OA\Property(property="number_compte", type="string", example="CIAZE3SD"),
     *              @OA\Property(property="phone", type="number", example="1234567898"),
     *              @OA\Property(property="devise", type="string", example="FRCFA"),
     *              @OA\Property(property="Status", type="string", example="pending"),
     *              @OA\Property(property="date_treatment", type="string", example="2022-08-11T09:25:53.000000Z"),
     *              @OA\Property(property="updated_at", type="string", example="2022-08-11T09:25:53.000000Z"),
     *              @OA\Property(property="created_at", type="string", example="2022-08-11T09:25:53.000000Z")
     *         )
     *     )
     * )
     */
    public function inter_show($inter_id)
    {

        $wallet_user = Auth::guard('api')->user();

        $wallet_solde = Wallet::where('sid_user_id', $wallet_user->id)->first();

        $show = $this->intersRepository->getInterById($inter_id);

        if ($wallet_solde->id != $show->wallet->id) {
            $message = __('message.is not wallet');
            return json_message_response($message, 333);
        }

        $invoice = new IntersSingleCollection($show);

        return response()->json([
            'success' => true,
            'message' => 'Inters payment details invoice.',
            'data' => $invoice
        ], 200);
    }

    /**
     * Delete Inter transaction
     * @OA\Delete (
     *      path="/user/inter/delete/{id}",
     *      tags={"Inter transfer User"},
     *      summary="Delete inter",
     *      description="Supprimer les paiements a l'internationnal", 
     *     @OA\Parameter(
     *         in="path",
     *         name="id",
     *         required=true,
     *         @OA\Schema(type="integer")
     *     ),
     *     @OA\Response(
     *         response=200,
     *         description="success",
     *         @OA\JsonContent(
     *             @OA\Property(property="msg", type="integer", example="delete virement success")
     *         )
     *     ),
     *  @OA\RequestBody(
     *         @OA\MediaType(
     *             mediaType="application/json",
     *             @OA\Schema(
     *                 @OA\Property(
     *                      type="object",
     *                      @OA\Property(
     *                          property="inter_id",
     *                          type="number"
     *                      ),
     *                 ),
     *                
     *             )
     *         )
     *      ),
     * )
     */
    public function delete_inter(Request $request)
    {

        try {

            $wallet_user = Auth::guard('api')->user();

            $wallet_solde = Wallet::where('sid_user_id', $wallet_user->id)->first();

            $wallet_inter = WalletInter::find($request->inter_id);

            if ($wallet_solde->id != $wallet_inter->wallet->id) {
                $message = __('message.is not wallet');
                return json_message_response($message, 333);
            }

            $wallet_inter->delete();
            return response()->json([
                'success' => true,
                'message' => 'Inter transfer has been successfully removed from your wallet'
            ], 200);
        } catch (\Exception $exception) {
            $message = __('message.is not wallet');
            return json_message_response($message, 333);
        }
    }

