    public function reload_card_inter($provider, $amount_reload_card) 
    {

          
        $wallet_user = Auth::guard('api')->user();

        $default_valeur = 2000000;

        //Valuer inter  bank
        $commission_inter = DepositCost::whereId(1)->first();


      try {


            if($provider == 64 || $provider == 65) 
            {
       
        
                if ($wallet_user->wallet->currencie->code == 'EUR' ||
                $wallet_user->wallet->currencie->code == 'DH' ||
                $wallet_user->wallet->currencie->code == 'Dt' ||
                $wallet_user->wallet->currencie->code == 'CEDI' ||
                $wallet_user->wallet->currencie->code == 'USD')
                {

                  $valeur_amount = $amount_reload_card * $wallet_user->wallet->currencie->value;
            
                     
                        // Verify valeur amount max in Landing the ROBUS
                    $valeur_end = $commission_inter->levelDeposits->where('is_inter_bank',true)->last();
                                
            
                    //  Conversion valeur
                    $conversion_valeur_end  = $valeur_end->amount_end /  $wallet_user->wallet->currencie->value;

            
                    if($conversion_valeur_end  < $amount_reload_card)

                    {
                        $commission_reload_inter_val_inter_receive = "Montant maxi est  : " .  $conversion_valeur_end;
            
                        $commission_reload_inter_val_inter_pay = "Montant maxi est  : " . $conversion_valeur_end;

                        return response()->json([
                            'success' => $commission_inter != null ? true : false,
                            'data' =>  [
                                    'amount_pay' => $commission_reload_inter_val_inter_pay,
                                    'amount_receive' => $commission_reload_inter_val_inter_receive,
                                ],
                        ], 200);
            
                    } else {
                        
                
                        foreach ($commission_inter->levelDeposits->where('is_inter_bank',true) as $amount_comission) 
                        {
            
                            if ($valeur_amount >= $amount_comission->amount_begin &&  $valeur_amount <= $amount_comission->amount_end) 
                            {
                            
                                if ($amount_comission->amount == null) {
            
                                    $valeur_cfa =   $amount_comission->percent * $valeur_amount;
                            
                                    $valeur_calcul_pay = $valeur_cfa / $wallet_user->wallet->currencie->value ;
            
                                    $commission_reload_inter_val_inter_pay = $valeur_cfa / $wallet_user->wallet->currencie->value;
                            
                                    // Valeur receive 
            
