    // Search wallet id 
    public function search_transaction_inter($search)
    {

        try {


            $data = Wallet::where('wallet_id', $search)
                ->where('status', true)
                ->first();

            return response()->json([
                'success' => $data != null ? true : false,
                'data' =>  [
                    'name' => $data->sidUser->firstname . ' ' . $data->sidUser->lastname,
                    'image' => $data->sidUser->image ?? null,
                ],
            ], 200);
        } catch (\Exception $exception) {
            return response()->json([
                'success' =>  false,
                'message' => 'Pas d\'utilisateur',
            ], 200);
        }
    }

    // Verify ceilling

      
    public function getWalletBankCardCeilingProperty()
    {
        $data = [];
        foreach (BankCard::where('created_by', Auth::guard('api')->user()->id)
            ->whereDate('created_at', Carbon::today())->whereStatus(1)->get() as $bank) {
            $data[] = $bank->amount;
        }

        return array_sum($data);
    }

